        self.window_seconds = window_seconds
        self._events = []

    def _prune(self, now):
        cutoff = now - self.window_seconds
        keep = 0
        n = len(self._events)
        while keep < n and self._events[keep] <= cutoff:
            keep += 1
        if keep:
            self._events = self._events[keep:]

