def dedupe_preserve_order(items: list) -> list:
    seen_hashable = set()
    seen_unhashable = []
    result = []
    for item in items:
        try:
            hash(item)
            is_hashable = True
        except TypeError:
            is_hashable = False

        if is_hashable:
            if item in seen_hashable:
                continue
            seen_hashable.add(item)
        else:
            if any(item == other for other in seen_unhashable):
                continue
            seen_unhashable.append(item)

        result.append(item)
    return result
