class RateWindow:
    """Fixed-size sliding window rate counter over a half-open interval."""

    def __init__(self, limit: int, window_seconds: float):
        self.limit = limit
        self.window_seconds = window_seconds
        self._events = []

    def _prune(self, now: float) -> None:
        cutoff = now - self.window_seconds
        self._events = [t for t in self._events if t > cutoff]

    def _live_count(self, now: float) -> int:
        return sum(1 for t in self._events if t <= now)

    def count(self, now: float) -> int:
        self._prune(now)
        return self._live_count(now)

    def allow(self, now: float) -> bool:
        self._prune(now)
        if self._live_count(now) < self.limit:
            self._events.append(now)
            return True
        return False
